package com.adaptivelearning.execution.application;import com.adaptivelearning.execution.domain.StudySessionEntity;import org.junit.jupiter.api.Test;import java.time.*;import static org.assertj.core.api.Assertions.*;
class StudySessionAllocationTest {@Test void splitsAcrossBusinessMidnight(){ZoneId zone=ZoneId.of("Asia/Shanghai");StudySessionEntity s=new StudySessionEntity();s.setStartedAt(ZonedDateTime.of(2026,7,20,23,50,0,0,zone).toInstant());s.setEndedAt(ZonedDateTime.of(2026,7,21,0,20,0,0,zone).toInstant());s.setEffectiveSeconds(1800L);var a=StudySessionService.allocate(s,zone);assertThat(a).hasSize(2);assertThat(a.get(0).effectiveSeconds()).isEqualTo(600);assertThat(a.get(1).effectiveSeconds()).isEqualTo(1200);}}
